  1	import type { Coordinates, Park } from "./types";
  2	
  3	/**
  4	 * Turns untrusted park records (e.g. the contents of `parks.sample.json`)
  5	 * into `Park` objects the UI can rely on.
  6	 *
  7	 * Policy: never invent data. A field that is missing, empty or malformed
  8	 * becomes `null` (or `[]`), and the UI says it isn't listed. A record is only
  9	 * dropped when it can't be shown at all — no usable id or name, or an id that
 10	 * duplicates an earlier record. Every dropped record or discarded value is
 11	 * reported in `warnings` so data problems are visible to maintainers.
 12	 */
 13	export function normalizeParks(input: unknown): {
 14	  parks: Park[];
 15	  warnings: string[];
 16	} {
 17	  const warnings: string[] = [];
 18	
 19	  if (!Array.isArray(input)) {
 20	    return { parks: [], warnings: ["Park data is not an array."] };
 21	  }
 22	
 23	  const seenIds = new Set<string>();
 24	  const parks: Park[] = [];
 25	
 26	  input.forEach((record: unknown, index) => {
 27	    const label = `Park #${index}`;
 28	
 29	    if (!isObject(record)) {
 30	      warnings.push(`${label}: skipped because it is not an object.`);
 31	      return;
 32	    }
 33	
 34	    const id = text(record.id);
 35	    if (id === null || !ID_PATTERN.test(id)) {
 36	      warnings.push(`${label}: skipped because it has no valid id.`);
 37	      return;
 38	    }
 39	    if (seenIds.has(id)) {
 40	      warnings.push(`${label}: skipped because id "${id}" is a duplicate.`);
 41	      return;
 42	    }
 43	
 44	    const name = text(record.name);
 45	    if (name === null) {
 46	      warnings.push(`${label} ("${id}"): skipped because it has no name.`);
 47	      return;
 48	    }
 49	
 50	    seenIds.add(id);
 51	    const warn = (message: string) => warnings.push(`"${id}": ${message}`);
 52	    const location = isObject(record.location) ? record.location : {};
 53	
 54	    parks.push({
 55	      id,
 56	      name,
 57	      description: optionalText(record.description, "description", warn),
 58	      coordinates: coordinates(location.lat, location.lng, warn),
 59	      address: optionalText(location.address, "address", warn),
 60	      amenities: amenitySlugs(record.amenities, warn),
 61	      hours: optionalText(record.hours, "hours", warn),
 62	      images: imageUrls(record.images, warn),
 63	      acreage: numberInRange(record.acreage, "acreage", warn, {
 64	        min: 0,
 65	        exclusiveMin: true,
 66	      }),
 67	      rating: numberInRange(record.rating, "rating", warn, { min: 0, max: 5 }),
 68	    });
 69	  });
 70	
 71	  parks.sort((a, b) => a.name.localeCompare(b.name, "en"));
 72	  return { parks, warnings };
 73	}
 74	
 75	/** Ids become URL path segments, so keep them to a URL-safe slug. */
 76	const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]*$/;
 77	
 78	type Warn = (message: string) => void;
 79	
 80	function isObject(value: unknown): value is Record<string, unknown> {
 81	  return typeof value === "object" && value !== null && !Array.isArray(value);
 82	}
 83	
 84	/** A non-empty, trimmed string, or `null`. */
 85	function text(value: unknown): string | null {
 86	  if (typeof value !== "string") return null;
 87	  const trimmed = value.trim();
 88	  return trimmed === "" ? null : trimmed;
 89	}
 90	
 91	/** Like `text`, but warns when a value is present and isn't text at all. */
 92	function optionalText(
 93	  value: unknown,
 94	  field: string,
 95	  warn: Warn,
 96	): string | null {
 97	  if (value !== null && value !== undefined && typeof value !== "string") {
 98	    warn(`ignored ${field} because it is not text.`);
 99	  }
100	  return text(value);
101	}
102	
103	function numberInRange(
104	  value: unknown,
105	  field: string,
106	  warn: Warn,
107	  range: { min?: number; max?: number; exclusiveMin?: boolean },
108	): number | null {
109	  if (value === null || value === undefined) return null;
110	  const valid =
111	    typeof value === "number" &&
112	    Number.isFinite(value) &&
113	    (range.min === undefined ||
114	      (range.exclusiveMin ? value > range.min : value >= range.min)) &&
115	    (range.max === undefined || value <= range.max);
116	  if (!valid) {
117	    warn(`ignored invalid ${field} ${JSON.stringify(value)}.`);
118	    return null;
119	  }
120	  return value;
121	}
122	
123	function coordinates(
124	  lat: unknown,
125	  lng: unknown,
126	  warn: Warn,
127	): Coordinates | null {
128	  if (lat == null && lng == null) return null;
129	  const valid =
130	    typeof lat === "number" &&
131	    typeof lng === "number" &&
132	    Number.isFinite(lat) &&
133	    Number.isFinite(lng) &&
134	    Math.abs(lat) <= 90 &&
135	    Math.abs(lng) <= 180 &&
136	    // (0, 0) is a common "unknown" placeholder, never a real park here.
137	    !(lat === 0 && lng === 0);
138	  if (!valid) {
139	    warn(
140	      `ignored invalid coordinates ${JSON.stringify({ lat, lng })}; the park will not appear on the map.`,
141	    );
142	    return null;
143	  }
144	  return { lat, lng };
145	}
146	
147	function stringList(value: unknown, field: string, warn: Warn): string[] {
148	  if (value === null || value === undefined) return [];
149	  if (!Array.isArray(value)) {
150	    warn(`ignored ${field} because it is not a list.`);
151	    return [];
152	  }
153	  const items = value.map(text).filter((item) => item !== null);
154	  if (items.length !== value.length) {
155	    warn(`ignored ${value.length - items.length} empty or invalid ${field}.`);
156	  }
157	  return [...new Set(items)];
158	}
159	
160	/** Amenity slugs need a letter or digit to make a readable label. */
161	function amenitySlugs(value: unknown, warn: Warn): string[] {
162	  return stringList(value, "amenities", warn).filter((slug) => {
163	    if (/[\p{Letter}\p{Number}]/u.test(slug)) return true;
164	    warn(`ignored amenity ${JSON.stringify(slug)} because it has no words.`);
165	    return false;
166	  });
167	}
168	
169	function imageUrls(value: unknown, warn: Warn): string[] {
170	  return stringList(value, "images", warn).filter((url) => {
171	    let protocol: string;
172	    try {
173	      protocol = new URL(url).protocol;
174	    } catch {
175	      protocol = "";
176	    }
177	    if (protocol === "https:" || protocol === "http:") return true;
178	    warn(
179	      `ignored image ${JSON.stringify(url)} because it is not an http(s) URL.`,
180	    );
181	    return false;
182	  });
183	}
  1	import "server-only";
  2	
  3	import rawParks from "../../../assets/parks.sample.json";
  4	import { normalizeParks } from "./normalize";
  5	import type { Park } from "./types";
  6	
  7	/*
  8	 * The dataset is a static file bundled at build time, so it is normalized
  9	 * once per server process. Swapping in an API later only means changing
 10	 * this module; pages depend on `getParks` / `getPark`, not on the file.
 11	 */
 12	const { parks, warnings } = normalizeParks(rawParks);
 13	
 14	if (warnings.length > 0) {
 15	  console.warn(
 16	    `[parks] ${warnings.length} data issue(s):\n  ${warnings.join("\n  ")}`,
 17	  );
 18	}
 19	
 20	export function getParks(): Park[] {
 21	  return parks;
 22	}
 23	
 24	export function getPark(id: string): Park | undefined {
 25	  return parks.find((park) => park.id === id);
 26	}
  1	/**
  2	 * A park after normalization. Every optional field is either a usable value
  3	 * or `null` (arrays are empty instead), so UI code never has to re-check
  4	 * the raw data's shape.
  5	 */
  6	export type Park = {
  7	  /** URL-safe identifier, unique across the dataset. */
  8	  id: string;
  9	  name: string;
 10	  description: string | null;
 11	  /** `null` when the source has no usable coordinates; such parks are listed but not mapped. */
 12	  coordinates: Coordinates | null;
 13	  address: string | null;
 14	  /** Amenity slugs as given in the source (e.g. `"dog-run"`), de-duplicated. */
 15	  amenities: string[];
 16	  /** Free-text opening hours exactly as published (e.g. `"Dawn to dusk"`). */
 17	  hours: string | null;
 18	  /** Absolute http(s) image URLs. They may still fail to load at runtime. */
 19	  images: string[];
 20	  acreage: number | null;
 21	  /** Rating on a 0–5 scale. The data doesn't say where ratings come from. */
 22	  rating: number | null;
 23	};
 24	
 25	export type Coordinates = { lat: number; lng: number };
 26	
 27	export type ParkWithCoordinates = Park & { coordinates: Coordinates };
 28	
 29	export function hasCoordinates(park: Park): park is ParkWithCoordinates {
 30	  return park.coordinates !== null;
 31	}

     1	/** Human-readable labels for amenity slugs that don't read well title-cased. */
     2	const AMENITY_LABELS: Record<string, string> = {
     3	  wifi: "Wi-Fi",
     4	  "dog-run": "Dog run",
     5	  "bike-path": "Bike path",
     6	  "splash-pad": "Splash pad",
     7	  "skate-park": "Skate park",
     8	  "kayak-launch": "Kayak launch",
     9	  "event-lawn": "Event lawn",
    10	  "gift-shop": "Gift shop",
    11	  "food-vendors": "Food vendors",
    12	  "picnic-areas": "Picnic areas",
    13	  "sports-fields": "Sports fields",
    14	  "water-fountain": "Water fountain",
    15	  "wildlife-viewing": "Wildlife viewing",
    16	  "accessible-paths": "Accessible paths",
    17	};
    18	
    19	/** `"dog-run"` → `"Dog run"`; unknown slugs fall back to sentence case. */
    20	export function amenityLabel(slug: string): string {
    21	  // Slugs are normalized to contain at least one letter or digit, so this
    22	  // never returns an empty label.
    23	  const known = AMENITY_LABELS[slug];
    24	  if (known) return known;
    25	  const words = slug.replace(/[-_]+/g, " ").trim();
    26	  return words.charAt(0).toUpperCase() + words.slice(1);
    27	}
    28	
    29	export function formatAcreage(acres: number): string {
    30	  const value = acres.toLocaleString("en-US", { maximumFractionDigits: 1 });
    31	  // Pluralize what's shown: 1.04 displays as "1", so "1 acre".
    32	  return `${value} ${value === "1" ? "acre" : "acres"}`;
    33	}
    34	
    35	export function formatRating(rating: number): string {
    36	  return `${rating.toFixed(1)} out of 5`;
    37	}
    38	
    39	/**
    40	 * A link that opens turn-by-turn directions in Google Maps, which needs no
    41	 * API key. Coordinates are used rather than the address because several
    42	 * addresses in the data are incomplete (e.g. just a street name).
    43	 */
    44	export function directionsUrl(lat: number, lng: number): string {
    45	  const params = new URLSearchParams({
    46	    api: "1",
    47	    destination: `${lat},${lng}`,
    48	  });
    49	  return `https://www.google.com/maps/dir/?${params}`;
    50	}
     1	import { amenityLabel } from "./format";
     2	import type { Park } from "./types";
     3	
     4	/**
     5	 * Case- and accent-insensitive search over the fields a resident is likely
     6	 * to type: name, address and amenities (by label, e.g. "dog run", or slug,
     7	 * e.g. "dog-run"). Every word in the query must match somewhere, so
     8	 * "brooklyn playground" narrows rather than widens the results.
     9	 *
    10	 * Descriptions are deliberately not searched: they mention things a park
    11	 * doesn't offer (e.g. "after they completed Central Park"), which would
    12	 * make results feel wrong.
    13	 */
    14	export function searchParks(parks: Park[], query: string): Park[] {
    15	  const words = normalize(query).split(" ").filter(Boolean);
    16	  if (words.length === 0) return parks;
    17	
    18	  return parks.filter((park) => {
    19	    const haystack = normalize(
    20	      [
    21	        park.name,
    22	        park.address ?? "",
    23	        ...park.amenities,
    24	        ...park.amenities.map(amenityLabel),
    25	      ].join(" "),
    26	    );
    27	    return words.every((word) => haystack.includes(word));
    28	  });
    29	}
    30	
    31	function normalize(text: string): string {
    32	  return text
    33	    .normalize("NFD")
    34	    .replace(/\p{Diacritic}/gu, "")
    35	    .toLowerCase()
    36	    .replace(/[^\p{Letter}\p{Number}]+/gu, " ")
    37	    .trim();
    38	}
