  1	"use client";
  2	
  3	import dynamic from "next/dynamic";
  4	import { useCallback, useEffect, useId, useMemo, useState } from "react";
  5	import { cn } from "@/lib/cn";
  6	import { searchParks } from "@/lib/parks/search";
  7	import { hasCoordinates, type Park } from "@/lib/parks/types";
  8	import { MapErrorBoundary } from "./map-error-boundary";
  9	import { ParkList } from "./park-list";
 10	import type { ShowOnMapRequest } from "./park-map";
 11	import { RenderWhenVisible } from "./render-when-visible";
 12	
 13	// Leaflet touches `window` on import, so the map only ever renders in the browser.
 14	const ParkMap = dynamic(() => import("./park-map"), {
 15	  ssr: false,
 16	  loading: () => (
 17	    <MapMessage>
 18	      <span role="status">Loading map…</span>
 19	    </MapMessage>
 20	  ),
 21	});
 22	
 23	type View = "list" | "map";
 24	
 25	/**
 26	 * The list and the map side by side (or one at a time on small screens),
 27	 * with a shared search and a shared selection: opening a marker highlights
 28	 * its card, and "Show on map" on a card opens its marker.
 29	 */
 30	export function ParkExplorer({ parks }: { parks: Park[] }) {
 31	  const [query, setQuery] = useState("");
 32	  const [selectedId, setSelectedId] = useState<string | null>(null);
 33	  const [showRequest, setShowRequest] = useState<ShowOnMapRequest | null>(null);
 34	  const [view, setView] = useState<View>("list");
 35	
 36	  const allMappable = useMemo(() => parks.filter(hasCoordinates), [parks]);
 37	  const results = useMemo(() => searchParks(parks, query), [parks, query]);
 38	  const mappableParks = useMemo(
 39	    () => results.filter(hasCoordinates),
 40	    [results],
 41	  );
 42	  const unmappedCount = results.length - mappableParks.length;
 43	  const mapInstructionsId = useId();
 44	
 45	  const updateQuery = (next: string) => {
 46	    setQuery(next);
 47	    // A park the search hides can't stay selected: its card and marker are
 48	    // gone, and Leaflet doesn't report its popup closing in that case.
 49	    if (
 50	      selectedId !== null &&
 51	      !searchParks(parks, next).some((park) => park.id === selectedId)
 52	    ) {
 53	      setSelectedId(null);
 54	    }
 55	  };
 56	
 57	  const showOnMap = useCallback((parkId: string) => {
 58	    setView("map");
 59	    setShowRequest((previous) => ({
 60	      parkId,
 61	      nonce: (previous?.nonce ?? 0) + 1,
 62	    }));
 63	  }, []);
 64	
 65	  useScrollSelectedCardIntoView(selectedId);
 66	
 67	  if (parks.length === 0) {
 68	    return (
 69	      <p className="rounded-lg border border-dashed border-border p-6">
 70	        No parks are listed yet. Please check back later.
 71	      </p>
 72	    );
 73	  }
 74	
 75	  return (
 76	    <div className="flex flex-col gap-4 lg:grid lg:grid-cols-[minmax(0,26rem)_minmax(0,1fr)] lg:items-start lg:gap-x-6">
 77	      <div className="flex flex-col gap-3 lg:col-start-1">
 78	        <SearchField value={query} onChange={updateQuery} />
 79	        <ResultCount
 80	          shown={results.length}
 81	          total={parks.length}
 82	          searching={query.trim() !== ""}
 83	        />
 84	        <div
 85	          role="group"
 86	          aria-label="Show parks as"
 87	          className="grid grid-cols-2 gap-1 rounded-lg border border-border bg-surface p-1 lg:hidden"
 88	        >
 89	          <ViewButton current={view} value="list" onSelect={setView}>
 90	            List
 91	          </ViewButton>
 92	          <ViewButton current={view} value="map" onSelect={setView}>
 93	            Map
 94	          </ViewButton>
 95	        </div>
 96	      </div>
 97	
 98	      <section
 99	        aria-label="Park list"
100	        className={cn(view === "map" && "hidden", "lg:col-start-1 lg:block")}
101	      >
102	        {results.length > 0 ? (
103	          <ParkList
104	            parks={results}
105	            selectedId={selectedId}
106	            onShowOnMap={showOnMap}
107	          />
108	        ) : (
109	          <div className="flex flex-col items-start gap-3 rounded-lg border border-dashed border-border p-6">
110	            <p>
111	              No parks match <q>{query.trim()}</q>. Try a park name, a street,
112	              or an amenity like “playground”.
113	            </p>
114	            <button
115	              type="button"
116	              onClick={() => updateQuery("")}
117	              className="inline-flex min-h-11 items-center rounded-md border border-border px-4 font-semibold hover:bg-surface-muted"
118	            >
119	              Clear search
120	            </button>
121	          </div>
122	        )}
123	      </section>
124	
125	      <section
126	        aria-labelledby="park-map-heading"
127	        className={cn(
128	          view === "list" && "hidden",
129	          "flex flex-col gap-2 lg:sticky lg:top-4 lg:col-start-2 lg:row-span-2 lg:row-start-1 lg:flex",
130	        )}
131	      >
132	        <h2 id="park-map-heading" className="sr-only">
133	          Map of parks
134	        </h2>
135	        <p id={mapInstructionsId} className="sr-only">
136	          Each park is a button on the map: Tab moves between them, Enter or
137	          Space opens a summary, and Escape closes it. When the map itself has
138	          focus, arrow keys move it and plus and minus zoom. The park list has
139	          the same information.
140	        </p>
141	        <div className="h-[70dvh] min-h-80 overflow-hidden rounded-lg border border-border bg-surface-muted lg:h-[calc(100dvh-2rem)]">
142	          {/* Gate on the full dataset, not search results, so the map isn't
143	              torn down (losing pan and zoom) when a search matches nothing. */}
144	          {allMappable.length > 0 ? (
145	            <MapErrorBoundary
146	              fallback={
147	                <MapMessage>
148	                  The map couldn’t be loaded. Every park is still in the list.
149	                </MapMessage>
150	              }
151	            >
152	              <RenderWhenVisible>
153	                <ParkMap
154	                  initialView={allMappable}
155	                  parks={mappableParks}
156	                  selectedId={selectedId}
157	                  showRequest={showRequest}
158	                  onSelect={setSelectedId}
159	                  instructionsId={mapInstructionsId}
160	                />
161	              </RenderWhenVisible>
162	            </MapErrorBoundary>
163	          ) : (
164	            <MapMessage>
165	              No parks have a location to show on the map.
166	            </MapMessage>
167	          )}
168	        </div>
169	        {unmappedCount > 0 && (
