  9	export const TILE_URL_PATTERN = "https://tile.openstreetmap.org/**";
 10	
 11	/**
 12	 * Every test runs offline from third parties: map tiles are stubbed (the OSM
 13	 * tile servers must not receive automated traffic, and tests shouldn't
 14	 * depend on them), and the sample data's placeholder image host is blocked,
 15	 * as it is unreachable in real life too.
 16	 *
 17	 * E2E_REAL_TILES=1 loads real tiles instead; only `pnpm screenshots` uses it.
 18	 */
 19	export const test = base.extend<{ stubExternalRequests: void }>({
 20	  stubExternalRequests: [
 21	    async ({ page }, use) => {
 22	      if (!process.env.E2E_REAL_TILES) {
 23	        await page.route(TILE_URL_PATTERN, (route) =>
 24	          route.fulfill({ contentType: "image/png", body: BLANK_TILE }),
 25	        );
 26	      }
 27	      await page.route("https://images.example.com/**", (route) =>
 28	        route.abort(),
 29	      );
 30	      await use();
 31	    },
 32	    { auto: true },
 33	  ],
 34	});
