  1	import AxeBuilder from "@axe-core/playwright";
  2	import type { Page } from "@playwright/test";
  3	import { expect, openMapView, test } from "./fixtures";
  4	
  5	/**
  6	 * Automated WCAG 2.2 AA checks. These catch a useful subset of problems
  7	 * (contrast, names, roles, landmarks); the keyboard tests in the other
  8	 * specs and manual screen reader testing cover what axe can't.
  9	 */
 10	async function expectNoViolations(page: Page) {
 11	  const results = await new AxeBuilder({ page })
 12	    .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"])
 13	    .analyze();
 14	  const violations = results.violations
 15	    .map((violation) => ({
 16	      ...violation,
 17	      nodes: violation.nodes.filter(
 18	        (node) => !isAcceptedMarkerOverlap(violation.id, node.html),
 19	      ),
 20	    }))
 21	    .filter((violation) => violation.nodes.length > 0);
 22	  const summary = violations.map(
 23	    (violation) =>
 24	      `${violation.id} (${violation.impact}): ${violation.help}\n  ${violation.nodes
 25	        .slice(0, 3)
 26	        .map((node) => node.target.join(" "))
 27	        .join("\n  ")}`,
 28	  );
 29	  expect(summary).toEqual([]);
 30	}
 31	
 32	/**
 33	 * At the zoomed-out city view on a phone, nearby park markers overlap, which
 34	 * axe reports under WCAG 2.5.8 (Target Size). Each marker is a 44x44 target
 35	 * on its own; overlap only happens when parks are close together. 2.5.8's
 36	 * "Equivalent" exception applies: every marker's function ("Show on map",
 37	 * open the park) is also available from the park list, whose controls are
 38	 * at least 44px tall. Only this rule, and only for markers, is accepted.
 39	 */
 40	function isAcceptedMarkerOverlap(ruleId: string, html: string) {
 41	  // axe truncates attribute values in `html`, but this attribute name is
 42	  // only ever set on map markers (see enhanceMarkerElement).
 43	  return ruleId === "target-size" && html.includes(" data-park-id=");
 44	}
